# E11: structural inventory of Juju 4.1 domains from the schema (DDL generated by the code) and the Go packages.
import re,glob,os,json,collections
SRC=os.path.expanduser('~/git/misc/juju-v2-preview')
def parse(ddl,scope):
    s=open(ddl).read()
    T={}
    for m in re.finditer(r'CREATE TABLE (\w+)\s*\((.*?)\n\);',s,flags=re.S):
        name,body=m.group(1),m.group(2)
        cols=[l.strip() for l in body.split('\n')]
        T[name]=dict(scope=scope,body=body,fks=set(re.findall(r'REFERENCES (\w+)',body)),
                     life='life_id' in body, status=name.endswith('_status') or name=='status_value' or 'status_id' in body,
                     uuid_pk=bool(re.search(r'uuid TEXT NOT NULL PRIMARY KEY|uuid TEXT PRIMARY KEY',body)),
                     unique=len(re.findall(r'UNIQUE',body)), check=len(re.findall(r'\bCHECK\b',body)))
    trig=re.findall(r'CREATE TRIGGER (\w+)',s)
    for t in T:
        T[t]['watched']=any(x==f'trg_log_{t}_insert' for x in trig)
        T[t]['immutable']=any(x.startswith(f'trg_{t}_immutable') or x.startswith(f'trg_{t}_unmodifiable') for x in trig)
    for m in re.finditer(r'CREATE UNIQUE INDEX \w+\s+ON (\w+)',s):
        if m.group(1) in T: T[m.group(1)]['unique']+=1
    return T
T={}
T.update(parse('model.ddl','model')); T.update({k+('@c' if k in T else ''):v for k,v in parse('controller.ddl','controller').items()})
# domain ownership by references in non-test Go state/service code
refs=collections.defaultdict(collections.Counter)
files=[f for f in glob.glob(SRC+'/domain/*/state/**/*.go',recursive=True)+glob.glob(SRC+'/domain/*/state/*.go')+glob.glob(SRC+'/domain/*/*.go') if not f.endswith('_test.go')]
files=sorted(set(files))
names=[t for t in T if '@' not in t]
pat=re.compile(r'\b('+'|'.join(sorted(map(re.escape,names),key=len,reverse=True))+r')\b')
writes=collections.defaultdict(collections.Counter)
CROSS={'removal','recovery','modelmigration','export','modelimport','schema','testing'}
for f in files:
    dom=f.split('/domain/')[1].split('/')[0]
    txt=open(f).read()
    for m in re.finditer(r'(INSERT INTO|INSERT OR \w+ INTO)\s+(\w+)',txt):
        if m.group(2) in T and dom not in CROSS: writes[m.group(2)][dom]+=1
    for m in pat.finditer(txt):
        if dom not in CROSS: refs[m.group(1)][dom]+=1
owner={}
for t in names:
    w=writes.get(t); r=refs.get(t)
    c=w if w else r
    owner[t]=c.most_common(1)[0][0] if c else None
json.dump({'owner':owner,'tables':{k:{kk:(sorted(vv) if isinstance(vv,set) else vv) for kk,vv in v.items() if kk!='body'} for k,v in T.items()}},open('tables.json','w'),indent=1)
D=collections.defaultdict(lambda: collections.Counter())
for t in names:
    d=owner[t] or '(unowned)'; v=T[t]
    D[d]['tables']+=1; D[d]['life']+=v['life']; D[d]['status']+=v['status']; D[d]['watched']+=v['watched']; D[d]['immutable']+=v['immutable']
    D[d]['fk_out_of_domain']+=sum(1 for r in v['fks'] if owner.get(r) not in (d,None) and r in owner)
    D[d]['fk_in_domain']+=sum(1 for r in v['fks'] if owner.get(r)==d)
print('%-22s %6s %5s %6s %7s %5s %5s %5s'%('domain','tables','life','status','watched','immut','fkIn','fkOut'))
for d,c in sorted(D.items(),key=lambda x:-x[1]['tables']):
    print('%-22s %6d %5d %6d %7d %5d %5d %5d'%(d,c['tables'],c['life'],c['status'],c['watched'],c['immutable'],c['fk_in_domain'],c['fk_out_of_domain']))
print('total model+controller tables',len(names),'unowned',sum(1 for t in names if not owner[t]))
